/** A new club. A missing field or a value of the wrong JSON type is `missing_field` / `invalid_field`; the rules on values are checked next and answer with the codes named on each field. Unknown fields are refused with `invalid_field`. */
export const CreateClubRequestSchema = z.object({
  /** 1-120 characters. */
  name: z.string(),
  /** Becomes the subdomain: 2-63 lowercase letters, digits or hyphens, no hyphen at either end, not reserved, not shaped like a UUID. Refused with `invalid_slug`. */
  slug: z.string(),
  /** Canonical IANA name, case-sensitive. Refused with `invalid_timezone`. */
  timezone: z.string(),
  /** ISO 4217, upper case. Refused with `invalid_currency`. */
  currency: z.string(),
  /** The club's contact address. */
  email: z.string(),
  phone: z.string().optional(),
  address: z.string().optional(),
  /** Given together with longitude. */
  latitude: z.number().optional(),
  /** Given together with latitude. */
  longitude: z.number().optional(),
  /** 1-50 courts. An empty list is `courts_required`, an unknown court_type `invalid_court_type`. */
  courts: z.array(z.object({
    /** 1-100 characters, unique within the club. */
    name: z.string(),
    /** A CourtType. */
    court_type: z.string(),
    /** Default false. */
    is_indoor: z.boolean().optional(),
    /** Up to 50 characters. */
    surface: z.string().optional(),
  })),
  /** 1-7 days; a day left out is closed. Bad hours are `invalid_hours`. */
  operating_hours: z.array(z.object({
    /** 0 = Sunday ... 6 = Saturday, each at most once. */
    day_of_week: z.number().int(),
    /** `HH:MM`, club timezone. */
    open_time: z.string(),
    /** `HH:MM`, later than `open_time`; `00:00` means midnight. */
    close_time: z.string(),
    /** Default false. */
    is_closed: z.boolean().optional(),
  })),
  /** Refused with `invalid_booking_rules`. */
  booking_rules: z.object({
    /** 5-1440. */
    slot_duration_minutes: z.number().int(),
    /** 5-1440, at most the slot. */
    min_duration_minutes: z.number().int(),
    /** 5-1440, at least the slot. */
    max_duration_minutes: z.number().int(),
    /** 0-365. */
    advance_booking_days: z.number().int(),
    /** 0-720. */
    cancellation_hours: z.number().int(),
  }),
  pricing: z.object({
    /** Price per hour on every court during opening hours, minor unit of `currency`; 0 creates no pricing rules. */
    default_price_cents: z.number().int(),
  }),
  /** Make this account the owner instead of the caller. Needs a provisioning grant that allows it. */
  owner_user_id: z.string().optional(),
});
