export const ProgramSchema = z.object({
  id: z.string(),
  club_id: ClubIdSchema,
  name: z.string(),
  description: z.string().nullable(),
  program_type: z.enum(["group_class", "private_lesson", "semi_private", "camp", "clinic"]),
  /** A member only ever sees `published` and `in_progress`. */
  status: z.enum(["draft", "published", "in_progress", "completed", "cancelled"]),
  /** Display colour, `#rrggbb`. */
  color: z.string(),
  /** Length of one session, in minutes. */
  duration_minutes: z.number().int(),
  /** The level the program is for. Null: open to every evaluated member. */
  skill_level_id: z.string().nullable(),
  /** That level's name, matched against the member's own level. */
  skill_level_name: z.string().nullable(),
  /** A program the player must have completed first. Null: none. */
  prerequisite_program_id: z.string().nullable(),
  court_type: z.enum(["tennis", "padel", "pickleball", "badminton", "squash", "other"]).nullable(),
  /** Confirmed places. */
  capacity: z.number().int(),
  /** Confirmed enrollments, everyone's. */
  enrollment_count: z.number().int(),
  /** Non-member price, in `currency`. */
  price_cents: z.number().int(),
  /** Price for a member with a membership tier. Null: no member price. */
  member_price_cents: z.number().int().nullable(),
  /** ISO 4217, e.g. `EUR`. */
  currency: z.string().nullable(),
  /** One of `free`, `program_total`, `per_session` (paid per session with passes) or `deposit`. */
  pricing_model: z.string(),
  /** What enrolling charges when `pricing_model` is `deposit`. */
  deposit_cents: z.number().int().nullable(),
  term_start: z.string(),
  /** Null: open-ended. */
  term_end: z.string().nullable(),
  /** The weekly pattern, club-local. Empty when none is set. */
  schedule_pattern: z.array(z.object({
    /** 0 is Sunday, 6 is Saturday. */
    day_of_week: z.number().int(),
    start_time: z.string(),
    end_time: z.string(),
  })),
  enrollment_deadline: z.string().nullable(),
  registration_open: z.boolean(),
  /** `instant`, or `staff`: an enrollment stays `pending` until the club confirms it. */
  registration_confirmation_mode: z.string(),
  minimum_age: z.number().int().nullable(),
  maximum_age: z.number().int().nullable(),
  /** Private programs are visible only to players enrolled in them. */
  is_private: z.boolean(),
  /** The caller has a pending, confirmed or waitlisted enrollment. */
  is_enrolled: z.boolean(),
});
export type Program = z.infer<typeof ProgramSchema>;

export const GetProgramResponseSchema = z.object({
  data: ProgramSchema,
});
export type GetProgramResponse = z.infer<typeof GetProgramResponseSchema>;

